import React, { useState } from 'react';
import './App.css'; // Make sure your CSS is set up for good styling

function App() {
  const [simOutput, setSimOutput] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [fileName, setFileName] = useState('');
  const [graphicsStatus, setGraphicsStatus] = useState(null);
  const [clicked, setClicked] = useState(false); // For "Get Started" animation

  // New state for step-by-step simulation
  const [simulationMode, setSimulationMode] = useState('full'); // 'full' or 'step'
  const [processId, setProcessId] = useState(null); // Stores the process_id from backend
  const [isStepping, setIsStepping] = useState(false); // True if step-by-step is active
  const [hasSimulationEnded, setHasSimulationEnded] = useState(false); // To disable buttons when finished

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setSelectedFile(file);
    setFileName(file.name);
    setSimOutput('');
    setGraphicsStatus(null);
    setProcessId(null); // Reset step-by-step state
    setIsStepping(false);
    setHasSimulationEnded(false);
  };

  const handleRunSimulation = async (mode) => {
    if (!selectedFile) return alert("Please upload a .bin file first.");

    const formData = new FormData();
    formData.append('binfile', selectedFile);
    formData.append('mode', mode); // Send the selected mode to the backend

    setLoading(true);
    setSimOutput('');
    setGraphicsStatus(null);
    setHasSimulationEnded(false); // Reset this flag

    try {
      const response = await fetch('http://localhost:5001/simulate', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        // If the response is not OK, it's likely a JSON error from the backend
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      if (mode === 'full') {
        const result = await response.text();
        setSimOutput(result);
        setGraphicsStatus("Graphics memory updated: 5 tiles, 3 palettes changed"); // Example static message
        setHasSimulationEnded(true); // Full simulation ends immediately
      } else if (mode === 'step') {
        const result = await response.json(); // Backend sends JSON for step mode start
        if (result.error) {
          throw new Error(result.error);
        }
        setProcessId(result.process_id);
        setIsStepping(true);
        setSimOutput("Step-by-step simulation started.\n" + result.initial_output);
        setGraphicsStatus("Graphics memory ready for stepping...");
      }

    } catch (error) {
      setSimOutput("❌ Error contacting backend: " + error.message);
      setProcessId(null); // Ensure cleanup on error
      setIsStepping(false);
      setHasSimulationEnded(true); // Treat as ended if an error occurs
    } finally {
      setLoading(false);
    }
  };

  const handleNextStep = async () => {
    if (!processId) return;

    setLoading(true); // Optional: show loading for each step
    try {
      const response = await fetch('http://localhost:5001/step_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ process_id: processId, command: '\n' }), // Send newline for any key
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();
      setSimOutput(prevOutput => prevOutput + "\n" + result.output); // Append new output

      if (result.terminated) {
        setSimOutput(prevOutput => prevOutput + "\n--- Simulation Ended ---");
        setProcessId(null);
        setIsStepping(false);
        setHasSimulationEnded(true);
      }

    } catch (error) {
      setSimOutput(prevOutput => prevOutput + "\n❌ Error during stepping: " + error.message);
      setProcessId(null); // Clean up
      setIsStepping(false);
      setHasSimulationEnded(true);
    } finally {
      setLoading(false);
    }
  };

  const handleStopSimulation = async () => {
    if (!processId) return;

    setLoading(true);
    try {
      const response = await fetch('http://localhost:5001/end_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ process_id: processId }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();
      setSimOutput(prevOutput => prevOutput + "\n" + (result.status || "Simulation stopped by user."));
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true); // Explicitly stopped, so mark as ended

    } catch (error) {
      setSimOutput(prevOutput => prevOutput + "\n❌ Error stopping simulation: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleClear = () => {
    // Also clear step-by-step related state
    if (isStepping && processId) {
      handleStopSimulation(); // Attempt to stop any active simulation first
    }
    setSimOutput('');
    setSelectedFile(null);
    setFileName('');
    setGraphicsStatus(null);
    setProcessId(null);
    setIsStepping(false);
    setHasSimulationEnded(false);
  };

  const handleGetStartedClick = () => {
    setClicked(true);
    setTimeout(() => {
      // Assuming 'simulate.html' is meant for a new page or perhaps this current page
      // If it's this page, you might just remove this navigation and continue with the UI.
      // For now, keeping it as is, but it seems odd for a React SPA.
      window.location.href = 'simulate.html'; // Consider if this is truly desired in a React app
    }, 150);
  };

  return (
      <div className="disassembler-container">
        <h2>⚙️ ZX16 Simulator Interface</h2>

        <input type="file" accept=".bin" onChange={handleFileChange} />
        {fileName && <p className="file-info">📄 Selected: {fileName}</p>}

        <div className="button-group" style={{ marginBottom: 10 }}>
          {/* Render buttons based on simulation state */}
          {!isStepping && (
              <>
                <button
                    onClick={() => handleRunSimulation('full')}
                    disabled={loading || !selectedFile || hasSimulationEnded}
                >
                  ▶️ {loading && simulationMode === 'full' ? 'Running Full...' : 'Run Full Simulation'}
                </button>
                <button
                    onClick={() => handleRunSimulation('step')}
                    disabled={loading || !selectedFile || hasSimulationEnded}
                >
                  🚶 {loading && simulationMode === 'step' ? 'Starting Step...' : 'Run Step-by-Step'}
                </button>
              </>
          )}

          {isStepping && !hasSimulationEnded && (
              <>
                <button onClick={handleNextStep} disabled={loading}>
                  ➡️ {loading ? 'Stepping...' : 'Next Step'}
                </button>
                <button onClick={handleStopSimulation} disabled={loading}>
                  ⏹️ Stop Simulation
                </button>
              </>
          )}

          <button onClick={handleClear} disabled={loading}>🧹 Clear</button>
        </div>

        {graphicsStatus && (
            <div style={{ marginBottom: 10, color: 'green', fontWeight: 'bold' }}>
              🎨 {graphicsStatus}
            </div>
        )}

        {simOutput && (
            <pre
                style={{
                  whiteSpace: 'pre-wrap',
                  maxHeight: '400px',
                  overflowY: 'auto',
                  border: '1px solid #ccc',
                  padding: '10px',
                  backgroundColor: '#f9f9f9',
                  fontSize: '14px',
                }}
            >
          {simOutput}
        </pre>
        )}

        {/* 🔘 Get Started Button */}
        <button
            className={`btn btn-primary ${clicked ? 'clicked' : ''}`}
            onClick={handleGetStartedClick}
            style={{ marginTop: '2rem' }}
        >
          🚀 Get Started
        </button>
      </div>
  );
}

export default App;
